      setSensitivity: setSensitivity,
      sensitivityRange: () => ({ min: SENS_MIN, max: SENS_MAX }),
      hint: () => hintFor(schemeOf(liveSchemeId()), liveSchemeId()),
      schemeYawOnly: schemeYawOnly,
